package dev.zomboid.isotacz;
public class InteractionChecks {static int n;static void check(boolean b){n++;if(!b)throw new AssertionError("interaction case "+n);}public static class Hit {String type;Object entity=new Object();Hit(String t){type=t;}public String getType(){return type;}public Object getEntity(){return entity;}}public static class Client {public Object player=new Object(),hitResult,crosshairPickEntity;public int uses;public void startUseItem(){uses++;}}
 public static void main(String[]args){Client mc=new Client();Hit block=new Hit("BLOCK");NativeInteraction.open(mc,block);check(mc.hitResult==block&&mc.crosshairPickEntity==null&&mc.uses==1);Hit entity=new Hit("ENTITY");NativeInteraction.open(mc,entity);check(mc.crosshairPickEntity==entity.entity&&mc.uses==2);check(NativeInteraction.gesture(true,true,true,true));check(!NativeInteraction.gesture(true,false,true,true));check(!NativeInteraction.gesture(true,true,true,false));mc.player=null;NativeInteraction.open(mc,block);check(mc.uses==2);System.out.println("Native interaction checks: "+n);}}
